/**
 * The only door between the deck and the project's numbers. Everything here is generated by
 * deck/scripts/export_data.py from results/*.json and src/prism; nothing is typed in by hand.
 */
import resultsJson from "./results.json";
import codeJson from "./code.json";
import gridJson from "./accounting_grid.json";
import factsJson from "./facts.json";

export type ResultFile =
  | "baselines"
  | "privacy_utility"
  | "membership"
  | "update_leakage"
  | "poisoning"
  | "free_riding"
  | "gossip"
  | "participation"
  | "sensitivity"
  | "ledger_audit"
  | "social_graph"
  | "dataset_card"
  | "flower_parity"
  | "calibration";

export const RESULT_FILES: ResultFile[] = [
  "baselines",
  "privacy_utility",
  "membership",
  "update_leakage",
  "poisoning",
  "free_riding",
  "gossip",
  "participation",
  "sensitivity",
  "ledger_audit",
  "social_graph",
  "dataset_card",
  "flower_parity",
  "calibration",
];

const results = resultsJson as unknown as Record<string, unknown>;

/** Reads a value from a result file. Path segments are joined by "/". Throws if any segment is absent. */
export function raw<T = unknown>(file: ResultFile, path: string): T {
  let node: unknown = results[file];
  if (node === undefined) throw new Error(`No result file "${file}" in results.json`);
  if (path === "") return node as T;
  for (const segment of path.split("/")) {
    if (node === null || typeof node !== "object") {
      throw new Error(`results/${file}.json has no "${path}" (stopped at "${segment}")`);
    }
    const next: unknown = Array.isArray(node) ? node[Number(segment)] : (node as Record<string, unknown>)[segment];
    if (next === undefined) throw new Error(`results/${file}.json has no "${path}" (stopped at "${segment}")`);
    node = next;
  }
  return node as T;
}

/** A measured number from a result file. Throws unless it is a finite number. */
export function m(file: ResultFile, path: string): number {
  const value = raw(file, path);
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new Error(`results/${file}.json "${path}" is not a finite number`);
  }
  return value;
}

export interface Fact {
  value: number | string;
  source: string;
  quote?: string;
}

const facts = factsJson as unknown as Record<string, Fact>;

/** A number that lives in a document or is counted at export time (run records, test count). */
export function fact(id: string): Fact {
  const entry = facts[id];
  if (!entry) throw new Error(`No fact "${id}" in facts.json`);
  return entry;
}

export function hasFact(id: string): boolean {
  return id in facts;
}

export interface CodeEntry {
  file: string;
  name: string;
  start: number;
  end: number;
  source: string;
}

const codeEntries = codeJson as unknown as Record<string, CodeEntry>;

/** Source of a function, class or method, keyed "path/under/prism.py::qualified.name". */
export function code(key: string): CodeEntry {
  const entry = codeEntries[key];
  if (!entry) throw new Error(`No code entry "${key}" in code.json`);
  return entry;
}

export interface AccountingGrid {
  rates: number[];
  rounds: number[];
  noise: number[];
  delta: number;
  users: number;
  accountant: string;
  /** epsilon[rate][rounds][noise]; null where the accountant returned no finite value. */
  epsilon: (number | null)[][][];
}

export const grid = gridJson as unknown as AccountingGrid;

export const fmt = {
  /** Plain number with a fixed number of digits (default 3). */
  n(x: number, digits = 3): string {
    return x.toFixed(digits);
  },
  /** Share as a percentage: 0.946 becomes "94.6%". */
  pct(x: number, digits = 1): string {
    return `${(x * 100).toFixed(digits)}%`;
  },
  /** NDCG and similar small scores, four digits. */
  ndcg(x: number): string {
    return x.toFixed(4);
  },
  /** Whole numbers with thousands separators. */
  int(x: number): string {
    return Math.round(x).toLocaleString("en-US");
  },
};
